    prompt_price = m.get('pricing', {}).get('prompt', '1')
    completion_price = m.get('pricing', {}).get('completion', '1')
    # Check if free (price is 0 or very close to 0)
    try:
        p = float(prompt_price)
        c = float(completion_price)
        if p == 0 and c == 0:
            free_models.append({
                'id': m['id'],
                'ctx': m.get('context_length', '?'),
                'prompt': prompt_price,
                'completion': completion_price
            })
    except:
        pass
for fm in sorted(free_models, key=lambda x: int(x['ctx']) if x['ctx'].isdigit() else 0, reverse=True)[:15]:
    print(f\"{fm['id']} | ctx: {fm['ctx']}\")
